(function(){
  try{
    const F=firebase.firestore;
    const isBank=p=>typeof p=="string"&&(p==="questionBank"||p.indexOf("questionBank/")===0);
    const kick=()=>{window.__bankDirty=!0;if(!_bankSyncStarted){window.__bankForce=!0;try{syncBank()}catch(_e){}}};
    const wrap=(P,names,getPath)=>{if(!P)return;names.forEach(m=>{const o=P[m];if(typeof o!="function"||o.__bk)return;P[m]=function(){try{if(isBank(getPath.apply(this,arguments)))kick()}catch(_e){}return o.apply(this,arguments)};P[m].__bk=1})};
    wrap(F.DocumentReference&&F.DocumentReference.prototype,["set","update","delete"],function(){return this.path});
    wrap(F.CollectionReference&&F.CollectionReference.prototype,["add"],function(){return this.path});
    wrap(F.WriteBatch&&F.WriteBatch.prototype,["set","update","delete"],function(r){return r&&r.path});
  }catch(_e){console.warn("[bank-guard] install fail",_e)}
})();

